import sys

def main():
    data = sys.stdin.read().split()
    n, k, m = int(data[0]), int(data[1]), int(data[2])
    adj = [[] for _ in range(n + 1)]
    for i in range(k):
        u, v, c = int(data[3 + 3 * i]), int(data[4 + 3 * i]), int(data[5 + 3 * i])
        adj[u].append((v, c))
        adj[v].append((u, c))
    INF = float('inf')
    parent = [0] * (n + 1)
    pw = [0] * (n + 1)
    order = [1]
    seen = [False] * (n + 1)
    seen[1] = True
    for u in order:
        for v, c in adj[u]:
            if not seen[v]:
                seen[v] = True
                parent[v] = u
                pw[v] = c
                order.append(v)
    dp = [None] * (n + 1)
    for v in reversed(order):
        cur = [INF, 0]
        for w, c in adj[v]:
            if w == parent[v]:
                continue
            ch = dp[w]
            new = cur + [INF] * (len(ch) - 1)
            for a in range(1, len(cur)):
                if cur[a] == INF:
                    continue
                for b in range(1, len(ch)):
                    if ch[b] == INF:
                        continue
                    val = cur[a] + ch[b] + c
                    if val < new[a + b]:
                        new[a + b] = val
            cur = new
        dp[v] = cur
    best = 1
    for s in range(1, len(dp[1])):
        if dp[1][s] != INF and 2 * dp[1][s] <= m:
            best = s
    print(best)

main()

