best = 1
for mask in range(1 << k):
    chosen = [edges[i] for i in range(k) if mask >> i & 1]
    cost = 2 * sum(c for _, _, c in chosen)
    if cost > m:
        continue
    reach = {1}
    changed = True
    while changed:
        changed = False
        for u, v, c in chosen:
            if (u in reach) != (v in reach):
                reach.add(u)
                reach.add(v)
                changed = True
    if all(u in reach and v in reach for u, v, c in chosen):
        best = max(best, len(reach))
print(best)

